# Lengthen the leading distractor where it came out shorter than the correct
# answer, so length doesn't give the answer away (see gen_lib.build).
LONGER = {
 1: ", which is why the standard library never returns error values",
 2: ", and a pointer receiver is only needed when the method is called from another package",
 4: ", which is why idiomatic Go code always prefers make over var for every slice",
 5: ", and nothing piles up even in very long-running loops",
 8: ", which also makes pprof and sync.Pool pointless",
 9: ", merging the responses once they all arrive",
 13: ", so raising it always makes any program faster",
 15: ", since renaming a field is not a breaking change for JSON consumers",
 18: ", which is how additive contract evolution is meant to work",
 20: ", even if the process crashes between the two calls",
 23: ", so reordering logic is never needed on your side",
 26: ", which also survives restarts and works across instances",
 28: ", and its activities run outside the workflow history",
 32: ", which also keeps every query fast",
 39: ", since contract tests already exercise the real database and broker",
}
Q = [(p, t, d, c, [w[0].rstrip('.') + LONGER[i] + '.'] + w[1:] if i in LONGER else w, e, m)
     for i, (p, t, d, c, w, e, m) in enumerate(Q, 1)]

assert len(Q) == 50, len(Q)
build("ezCater Integration Hub interview questions", M, Q, sys.argv[1])
